  Object.assign(sqToEn,{'Promovo llogarinë':'Promote account','Promovo llogarinë tënde':'Promote your account','Zgjidh pakon për profilin tënd. Pas aktivizimit mund të publikosh deri në kufirin e postimeve të përfshira.':'Choose a package for your profile. Once activated, you can publish up to the included post limit.','Zgjidh pakon dhe kufirin e postimeve':'Choose a package and posting limit','Nuk ke pako promovuese aktive':'You have no active promotion package','Publikimet falas vazhdojnë; zgjidh Plus, Premium ose Elite për promovim dhe kufi postimesh.':'Free listings remain available; choose Plus, Premium, or Elite for promotion and a post limit.','postime të përdorura':'posts used','postime të publikuara':'published posts','në dispozicion':'available','Llogari e promovuar':'Promoted account','Pas verifikimit aktivizohen':'After verification, these will be activated:','Kërkesa për promovimin e llogarisë u ruajt.':'The account promotion request was saved.','Pako falas nuk sponsorizon llogarinë.':'The free package does not sponsor the account.','Pakoja falas nuk sponsorizon llogarinë. Mund të vazhdosh me publikimet e zakonshme falas.':'The free package does not sponsor the account. You can continue with regular free listings.','Kërko pagesë manuale':'Request manual payment','Aktivizo falas':'Continue for free','Zgjidh një paketë për llogarinë':'Choose an account package','Ke përdorur limitin prej':'You have reached the limit of','postimesh të pakos':'posts in the package','postime promovuese':'promoted posts','Pako Plus':'Plus package','Pako Premium':'Premium package','Pako Elite':'Elite package'});
