  const reverse={};for(const [sq,en] of Object.entries(sqToEn))if(!(en in reverse))reverse[en]=sq;
  const attrs=['placeholder','aria-label','title','alt'];
  const textRecords=new WeakMap(),attributeRecords=new WeakMap();
  let language=localStorage.getItem('autopjese-language-v1')==='en'?'en':'sq';
  function swap(value,target){const map=target==='en'?sqToEn:reverse;const trimmed=value.trim();if(!trimmed)return value;if(map[trimmed])return value.replace(trimmed,map[trimmed]);let out=value;const pairs=Object.entries(map).filter(([from])=>from.length>3).sort((a,b)=>b[0].length-a[0].length);for(const [from,to] of pairs)out=out.split(from).join(to);return out}
  function translateText(node){let record=textRecords.get(node),current=node.nodeValue;if(!record||current!==record.translated){record={original:current,translated:current};textRecords.set(node,record)}const next=swap(record.original,language);if(next!==current)node.nodeValue=next;record.translated=next}
  function translateAttribute(el,attr){let records=attributeRecords.get(el);if(!records){records={};attributeRecords.set(el,records)}const current=el.getAttribute(attr);if(current===null)return;let record=records[attr];if(!record||current!==record.translated){record={original:current,translated:current};records[attr]=record}const next=swap(record.original,language);if(next!==current)el.setAttribute(attr,next);record.translated=next}
  function translateTree(root){if(!root)return;if(root.nodeType===Node.TEXT_NODE){translateText(root);return}const elements=root.nodeType===Node.ELEMENT_NODE?[root,...root.querySelectorAll('*')]:[];for(const el of elements)if(el.tagName==='OPTION'&&!el.hasAttribute('value'))el.setAttribute('value',el.textContent.trim());const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode()))if(node.nodeValue.trim())translateText(node);for(const el of elements)for(const attr of attrs)translateAttribute(el,attr)}
  function setLanguage(next,save=true){language=next==='en'?'en':'sq';document.documentElement.lang=language;translateTree(document.body);const code=document.getElementById('language-code'),button=document.getElementById('language-toggle');if(code)code.textContent=language.toUpperCase();if(button){const label=language==='en'?'Switch to Albanian':'Ndrysho në anglisht';button.setAttribute('aria-label',label);button.title=label}if(save)try{localStorage.setItem('autopjese-language-v1',language)}catch{}}
  function locale(){return language==='en'?'en-GB':'sq-XK'}
  const observer=new MutationObserver(records=>{for(const record of records){if(record.type==='childList')record.addedNodes.forEach(node=>{if(node.nodeType===Node.ELEMENT_NODE||node.nodeType===Node.TEXT_NODE)translateTree(node)});else if(record.type==='characterData')translateText(record.target)}});
  setLanguage(language,false);observer.observe(document.body,{subtree:true,childList:true,characterData:true});
